R,C=20,29
g=[[4]*C for _ in range(R)]
def rect(r1,c1,r2,c2,color):
    for r in range(r1,r2+1):
        for c in range(c1,c2+1):
            if r in (r1,r2) or c in (c1,c2): g[r][c]=color
# boundaries (0-indexed)
rect(1,1,7,7,9)
rect(4,20,11,27,9)
rect(11,1,14,4,5)
rect(12,12,16,16,6)
# fill cavities
for r1,c1,r2,c2 in [(2,2,6,6),(5,21,10,26),(12,2,13,3),(13,13,15,15)]:
    for r in range(r1,r2+1):
        for c in range(c1,c2+1): g[r][c]=7
print(g)

# Change the two even-width/height cavities to 2, leaving the odd interiors 7.
for r1,c1,r2,c2 in [(5,21,10,26),(12,2,13,3)]:
    for r in range(r1,r2+1):
        for c in range(c1,c2+1): g[r][c]=2
print(g)
